import{z as p,x as A,o as l,c as B,q as t,j as E,D as e,d as r,s,S as o,b as n}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"素数分布与生成","description":"","frontmatter":{"title":"素数分布与生成","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/prime-generation.md","filePath":"cs/prime-generation.md","lastUpdated":1791413859000}'),d={name:"cs/prime-generation.md"};function m(h,a,u,D,c,R){const i=A("Mermaid");return l(),B("div",null,[a[2]||(a[2]=t('<h1 id="素数分布与生成" tabindex="-1">素数分布与生成 <a class="header-anchor" href="#素数分布与生成" aria-label="Permalink to &quot;素数分布与生成&quot;">​</a></h1><div class="epigraph"><p>素数定理：$\\pi(x)\\sim x/\\ln x$。随机奇数被素的概率约 $2/\\ln n$，故重复抽检（Miller–Rabin）即可生成密码学素数。</p><footer>—— 据 Hadamard；de la Vallée Poussin；Knuth 卷 2；Menezes, van Oorschot and Vanstone 整理</footer></div><p>上一课<a href="/cs/miller-rabin">Miller–Rabin</a> 会检验给定 \\(n\\)。缺口是<strong>生成</strong>：随机选 \\(n\\) 比特奇数，测素性，失败再抽。素数定理保证期望试验次数 \\(O(n)\\)。安全素数、强素数是额外约束。本课不证素数定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\pi(x)\\approx x/\\ln x\\)，于是 \\(n\\) 比特素数密度 \\(\\sim 1/n\\)。偶数扔掉，再过小素筛（试除 \\(3,5,7,\\ldots\\)）减少 MR 次数。RSA 要两个同量级素 \\(p,q\\)；DH 要 \\(p\\) 使 \\(p-1\\) 有大素因子（上一课 DLP）。Maurer、Shawe-Taylor 可证明素数构造点名；实践仍是随机 + MR。</p><p>不要用确定性「第 \\(k\\) 个素数公式」当算法——没有可用的闭式生成器。</p><h3 id="密度不是随机性的证明" tabindex="-1">密度不是随机性的证明 <a class="header-anchor" href="#密度不是随机性的证明" aria-label="Permalink to &quot;密度不是随机性的证明&quot;">​</a></h3><p>素数看起来无公式，仍可能有未知结构。密码学把「随机素数」当工作假设加 MR 错误界，不是 Riemann 假设课。</p><p><span class="marginnote">素数定理 1896。Cramér 模型点名。HAC（Menezes et al.）第 4 章生成。FIPS 186 的方法是标准实践，本课不抄参数表。</span></p><p><span class="marginnote">直觉类比：找大素数像在沙滩上筛金子——「金子」（素数）很稀，但你有一台极快的验金仪（Miller–Rabin）：抓一把验一把，不中就换，几百次内几乎必然淘到，且定理告诉你沙里确实有金。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估 1024 比特：\\(1/\\ln(2^{1024})\\approx 1/710\\)，奇数再 \\(\\times 2\\)，期望几十到上百次 MR。写筛 + MR 流程。点名：共用素数、过小 \\(p-q\\) 是实现事故，不是分布定理。</p><p><span class="marginnote">数字实例：1024 比特时 1/ln(2^1024)≈1/710，即平均约 710 个数里有一个素；只抽奇数把密度翻倍到约 1/355，小素筛再淘汰大半合数——于是几十到上百轮 MR 就够，素数定理把「找素数」变成可预估的工作量。</span></p>',13)),(l(),E(o,null,{default:e(()=>[s(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%CF%80(x)~x%2Fln%20x%22%5D%20--%3E%20DEN%5B%22n%20%E6%AF%94%E7%89%B9%E5%AF%86%E5%BA%A6%20~1%2Fn%22%5D%0A%20%20DEN%20--%3E%20SAMP%5B%22%E9%9A%8F%E6%9C%BA%E5%A5%87%E6%95%B0%22%5D%0A%20%20SAMP%20--%3E%20MR%5B%22Miller%E2%80%93Rabin%22%5D%0A%20%20MR%20--%3E%20PRIME%5B%22%E8%BE%93%E5%87%BA%E7%B4%A0%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"数论单元的「随机素」与平均复杂度课的 OWF 衔接：RSA 模是这种抽样的输出。下一课换群：椭圆曲线，素数仍作为域的特征或阶的因子出现。",-1)),a[5]||(a[5]=n("p",null,"把生成流程拆成漏斗，看每道关卡各丢掉什么候选：",-1)),(l(),E(o,null,{default:e(()=>[s(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E5%80%99%E9%80%89%E6%B1%A0%EF%BC%9A%E9%9A%8F%E6%9C%BA%201024%20%E6%AF%94%E7%89%B9%E5%A5%87%E6%95%B0%22%5D%20--%3E%20S1%5B%22%E5%B0%8F%E7%B4%A0%E7%AD%9B%EF%BC%9A%E8%AF%95%E9%99%A4%203%2C5%2C7%2C...%22%5D%0A%20%20S1%20--%3E%20K1%5B%22%E7%BA%A6%E5%9B%9B%E5%88%86%E4%B9%8B%E4%B8%89%E7%9A%84%E5%90%88%E6%95%B0%E8%A2%AB%E5%B0%B1%E5%9C%B0%E4%B8%A2%E5%BC%83%22%5D%0A%20%20K1%20--%3E%20S2%5B%22%E5%B9%B8%E5%AD%98%E8%80%85%E8%BF%9B%E5%85%A5%20Miller%E2%80%93Rabin%22%5D%0A%20%20S2%20--%3E%20K2%5B%22%E5%8D%95%E8%BD%AE%20MR%20%E6%94%BE%E8%A1%8C%E5%90%88%E6%95%B0%E7%9A%84%E6%A6%82%E7%8E%87%E7%BA%A6%201%2F4%22%5D%0A%20%20K2%20--%3E%20S3%5B%22%E5%A4%9A%E8%BD%AE%E7%8B%AC%E7%AB%8B%20MR%20%E5%85%A8%E8%BF%87%E6%89%8D%E6%8E%A5%E5%8F%97%22%5D%0A%20%20S3%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%201024%20%E6%AF%94%E7%89%B9%E7%B4%A0%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">为什么重要：小素筛不是为了正确性，是为了省钱——一次试除远比一轮 MR 便宜，先用便宜关卡滤掉 75% 的合数，昂贵关卡只处理幸存者，总开销显著下降。</span></p><p>Dirichlet：算术级数里也有无穷素，故可要求 \\(p\\equiv 3\\pmod 4\\) 等。</p><p>Dirichlet：互素的 \\(a,n\\) 上 \\(a+kn\\) 有无穷素，故可强制 \\(p\\equiv 3\\pmod 4\\)（Tonelli 简单）。安全素数更稀，抽样要更久。不要从低位素数表「拼」一个大数当 \\(p\\)。共用 NIST 素数在 DH 上可接受（公开参数），RSA 的 \\(p,q\\) 必须新抽。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证素数定理，不引入 ζ 函数。不讨论量子 Shor 对已生成模数的威胁（BQP 课已点名）。后课默认：密码学素数 = 密度保证下的随机 + MR。下一课椭圆曲线群。</p><p>密度 \\(1/\\ln n\\) 让随机抽样可行，不是给出第 \\(k\\) 个素数公式。RSA 的 \\(p,q\\) 要独立新抽；DH 可用标准安全素数。筛掉小素因子只是为了少跑 MR。</p><p><span class="marginnote">常见误区：以为 MR「会放行合数」就不能用于密码学。单轮放行概率约 1/4，独立跑 40 轮后错误率低于 2^-80——比内存里翻转一个比特的概率还小。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>素数定理给出 \\(n\\) 比特密度 \\(\\sim 1/n\\)，抽样可行。</li><li>生成 = 随机 + 筛 + Miller–Rabin。</li><li>DH/RSA 还要对 \\(p-1\\)、\\(p,q\\) 间距加约束。</li><li>出处：Hadamard；de la Vallée Poussin；HAC；Knuth。</li></ul>',9))])}const b=p(d,[["render",m]]);export{S as __pageData,b as default};
